pragma solidity 0.8.24;

import {AccessControlDefaultAdminRulesUpgradeable} from "@openzeppelin/contracts-upgradeable/access/extensions/AccessControlDefaultAdminRulesUpgradeable.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IBascule} from "../bascule/interfaces/IBascule.sol";
import {INativeLBTC} from "./interfaces/INativeLBTC.sol";
import {INotaryConsortium} from "../consortium/INotaryConsortium.sol";
import {IAssetRouter} from "./interfaces/IAssetRouter.sol";
import {Actions} from "../libs/Actions.sol";
import {Assert} from "./libraries/Assert.sol";
import {IBridgeToken} from "../interfaces/IBridgeToken.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @title BridgeToken adapter for AssetRouter
/// @author Lombard.Finance
/// @notice This contract is part of the Lombard.Finance protocol.
/// @custom:security-contact legal@lombard.finance
contract BridgeTokenAdapter is
    INativeLBTC,
    AccessControlDefaultAdminRulesUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    /// @param prevValue The previous address of BridgeToken contract
    /// @param newValue The new address of BridgeToken contract
    event BridgeTokenChanged(
        address indexed prevValue,
        address indexed newValue
    );

    error InvalidRecipient(address expected, address actual);

    /// @custom:storage-location erc7201:lombardfinance.storage.BridgeTokenAdapter
    struct BridgeTokenAdapterStorage {
        // slot: 20 + 8 + 1 | 29/32
        INotaryConsortium consortium;
        // slot: 20 | 20/32
        address treasury;
        // slot: 20 | 20/32
        IBascule bascule;
        // other slots by 32
        mapping(bytes32 => bool) usedPayloads; // sha256(rawPayload) => used
        IAssetRouter assetRouter;
        IBridgeToken bridgeToken; // the token to adapt
    }

    /// @dev keccak256(abi.encode(uint256(keccak256("lombardfinance.storage.BridgeTokenAdapter")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant BRIDGE_TOKEN_ADAPTER_STORAGE_LOCATION =
        0x12da876cd9d34462e8cb4fac06f079885ba1e4376e1cdc9acc16182cfc348a00;

    /// @notice The pauser role may pause the contract.
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    /// @notice The minter role is able to mint new tokens.
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    /// @dev https://docs.openzeppelin.com/upgrades-plugins/1.x/writing-upgradeable#initializing_the_implementation_contract
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// INTIALIZERS ///

    /// @dev Proxy initializer
    /// @param consortium The consortium contract address
    /// @param treasury The treasury address
    /// @param initialOwner The initial owner of the contract
    /// @param initialOwnerDelay The initial transfer ownership delay
    /// @param bridgeToken The BridgeToken contract address
    function initialize(
        address consortium,
        address treasury,
        address initialOwner,
        uint48 initialOwnerDelay,
        address bridgeToken
    ) external initializer {
        __AccessControlDefaultAdminRules_init(initialOwnerDelay, initialOwner);
        __ReentrancyGuard_init();
        __BridgeTokenAdapter_init(bridgeToken, consortium, treasury);
        __Pausable_init();
    }

    function __BridgeTokenAdapter_init(
        address bridgeToken,
        address consortium,
        address treasury
    ) internal onlyInitializing {
        _changeConsortium(consortium);
        _changeTreasury(treasury);
        _changeBridgeToken(bridgeToken);
    }

    /// ONLY OWNER FUNCTIONS ///

    /// @notice Change the trusted consortium
    /// @param newVal The address of the new consortium contract
    /// @custom:access Caller must have DEFAULT_ADMIN_ROLE
    function changeConsortium(
        address newVal
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _changeConsortium(newVal);
    }

    /// @notice Change the treasury address
    /// @param newVal The address of the new treasury
    /// @custom:access Caller must have DEFAULT_ADMIN_ROLE
    function changeTreasuryAddress(
        address newVal
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _changeTreasury(newVal);
    }

    /// @notice Pause contract
    /// @dev Each non owner method should be paused
    /// @custom:access Caller must have PAUSER_ROLE
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /// @notice Unpause contract
    /// @custom:access Caller must have DEFAULT_ADMIN_ROLE
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    /// @notice Change the address of the Bascule drawbridge contract.
    /// @dev Setting the address to 0 disables the Bascule check.
    /// @param newVal The new address.
    /// @custom:events Emits a [BasculeChanged] event.
    /// @custom:access Caller must have DEFAULT_ADMIN_ROLE
    function changeBascule(
        address newVal
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _changeBascule(newVal);
    }

    /// @notice Change the address of [AssetRouter] contract.
    /// @param newVal The new address.
    /// @custom:events Emits a [AssetRouterChanged] event.
    /// @custom:access Caller must have DEFAULT_ADMIN_ROLE
    function changeAssetRouter(
        address newVal
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _changeAssetRouter(newVal);
    }

    /// @dev mainly used for migration testing TODO: remove later
    /// @param newVal The address of the new BridgeToken contact
    function changeBridgeToken(
        address newVal
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _changeBridgeToken(newVal);
    }

    /// GETTERS ///

    /// @return consortium The consortium contract address
    function getConsortium() external view virtual returns (INotaryConsortium) {
        return _getBridgeTokenAdapterStorage().consortium;
    }

    /// @return assetRouter The asset router contract address
    function getAssetRouter() external view override returns (address) {
        return address(_getBridgeTokenAdapterStorage().assetRouter);
    }

    /// @return isNative If true, then token is native bitcoin on the chain
    function isNative() public pure returns (bool) {
        return true;
    }

    /// @dev Proxy method from asset router
    /// @return isRedeemEnabled If true, then redeem is enabled
    function isRedeemsEnabled() public view override returns (bool) {
        (, , bool isRedeemEnabled) = _getBridgeTokenAdapterStorage()
            .assetRouter
            .tokenConfig(address(this));
        return isRedeemEnabled;
    }

    /// @return treasury The treasury address
    function getTreasury() public view override returns (address) {
        return _getBridgeTokenAdapterStorage().treasury;
    }

    /// @return redeemFee The fee for redeem
    function getRedeemFee() public view returns (uint256) {
        (uint256 redeemFee, , ) = _getBridgeTokenAdapterStorage()
            .assetRouter
            .tokenConfig(address(this));
        return redeemFee;
    }

    /// @dev Not implemented
    function getFeeDigest(
        uint256,
        uint256
    ) external view override returns (bytes32) {
        revert();
    }

    /// @notice Get Bascule contract.
    /// @return The address of Bascule DrawBridge contract
    function getBascule() external view returns (IBascule) {
        return _getBridgeTokenAdapterStorage().bascule;
    }

    /// USER ACTIONS ///

    /// @notice Mint NativeLBTC to the specified address
    /// @param to The address to mint to
    /// @param amount The amount of NativeLBTC to mint
    /// @custom:access The caller must have MINTER_ROLE
    function mint(
        address to,
        uint256 amount
    ) external override whenNotPaused onlyRole(MINTER_ROLE) nonReentrant {
        // the mint can be not backed by Bitcoin deposit
        // set vout as dummy `type(uint256).max` to make it impossible on Bitcoin network
        // could help to filter out such events
        _getBridgeTokenAdapterStorage().bridgeToken.mint(
            to,
            amount,
            address(0),
            0,
            bytes32(0),
            type(uint256).max
        );
    }

    /// @notice Mint NativeLBTC in batches
    /// @param to The addresses to mint to
    /// @param amount The amounts of NativeLBTC to mint
    /// @custom:access The caller must have MINTER_ROLE
    function batchMint(
        address[] calldata to,
        uint256[] calldata amount
    ) external onlyRole(MINTER_ROLE) nonReentrant {
        _batchMint(to, amount);
    }

    function _batchMint(
        address[] calldata to,
        uint256[] calldata amount
    ) internal whenNotPaused {
        Assert.equalLength(to.length, amount.length);
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();

        for (uint256 i; i < to.length; ++i) {
            // the mint can be not backed by Bitcoin deposit
            // set vout as dummy `type(uint256).max` to make it impossible on Bitcoin network
            // could help to filter out such events
            $.bridgeToken.mint(
                to[i],
                amount[i],
                address(0),
                0,
                bytes32(0),
                type(uint256).max
            );
        }
    }

    /// @notice Mint NativeLBTC by proving DepositV1 payload
    /// @param rawPayload The message with the stake data
    /// @param proof Signature of the consortium approving the mint
    function mintV1(
        bytes calldata rawPayload,
        bytes calldata proof
    ) external nonReentrant {
        _mintV1(rawPayload, proof);
    }

    /// @notice Mint NativeLBTC in batches by DepositV1 payloads
    /// @param payload The messages with the stake data
    /// @param proof Signatures of the consortium approving the mints
    function batchMintV1(
        bytes[] calldata payload,
        bytes[] calldata proof
    ) external nonReentrant {
        Assert.equalLength(payload.length, proof.length);

        for (uint256 i; i < payload.length; ++i) {
            // Pre-emptive check if payload was used. If so, we can skip the call.
            bytes32 payloadHash = sha256(payload[i]);
            if (_getBridgeTokenAdapterStorage().usedPayloads[payloadHash]) {
                emit BatchMintSkipped(payloadHash, payload[i]);
                continue;
            }

            _mintV1(payload[i], proof[i]);
        }
    }

    /// TODO: remove after used
    /// @dev Allows to skip minting if recipient is address(this)
    /// @notice accept Btc deposited to adapter, but not mint
    /// @param payload The deposit payload to spend without mint
    /// @param proof The consortium signatures
    function spendDeposit(
        bytes calldata payload,
        bytes calldata proof
    ) external {
        Assert.selector(payload, Actions.DEPOSIT_BTC_ACTION_V1);
        Actions.DepositBtcActionV1 memory action = Actions.depositBtcV1(
            payload[4:]
        );
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();

        bytes32 payloadHash = sha256(payload);
        if ($.usedPayloads[payloadHash]) {
            revert PayloadAlreadyUsed();
        }
        $.consortium.checkProof(payloadHash, proof);
        $.usedPayloads[payloadHash] = true;

        if (action.recipient != address(this)) {
            revert InvalidRecipient(address(this), action.recipient);
        }

        emit MintProofConsumed(action.recipient, payloadHash, payload);
    }

    /// @dev Implements [transferFrom] to mimic ERC20 token behaviour. Expose to caller ability to spend [BridgeToken] allowed to the adapter.
    /// @param from The address to move `amount` from
    /// @param to The address to move `amount` to
    /// @param amount The amount to move
    /// @custom:access The caller mush have MINTER_ROLE.
    function transferFrom(
        address from,
        address to,
        uint256 amount
    ) external whenNotPaused onlyRole(MINTER_ROLE) {
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();
        SafeERC20.safeTransferFrom($.bridgeToken, from, address(this), amount);
        SafeERC20.safeTransfer($.bridgeToken, to, amount);
    }

    /// @dev Implements [burn] to mimic IBaseLBTC token interface. Expose to caller ability to burn [BridgeToken] allowed to the adapter.
    /// @param amount The amount of tokens to burn
    /// @custom:access The caller mush have MINTER_ROLE.
    function burn(
        uint256 amount
    ) external override whenNotPaused onlyRole(MINTER_ROLE) {
        // address(this) should be approved to burn `from`
        _getBridgeTokenAdapterStorage().bridgeToken.burnFrom(
            _msgSender(),
            amount
        );
    }

    /// @dev Implements [burn] to mimic IBaseLBTC token interface. Expose to caller ability to burn [BridgeToken] allowed to the adapter.
    /// @param from The address to burn `amount` from
    /// @param amount The amount to burn
    /// @custom:access The caller mush have MINTER_ROLE.
    function burn(
        address from,
        uint256 amount
    ) external override whenNotPaused onlyRole(MINTER_ROLE) {
        // address(this) should be approved to burn `from`
        _getBridgeTokenAdapterStorage().bridgeToken.burnFrom(from, amount);
    }

    /// PRIVATE FUNCTIONS ///

    /// @notice Mint using payload
    function _mintV1(
        bytes calldata rawPayload,
        bytes calldata proof
    ) internal whenNotPaused returns (address, uint256) {
        Assert.selector(rawPayload, Actions.DEPOSIT_BTC_ACTION_V1);
        Actions.DepositBtcActionV1 memory action = Actions.depositBtcV1(
            rawPayload[4:]
        );
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();

        /// make sure that hash of payload not used before
        /// need to check sha256 hash from payload without selector
        bytes32 payloadHash = sha256(rawPayload);
        bytes32 legacyHash = keccak256(rawPayload[4:]); // TODO: remove when bascule support sha256
        if ($.usedPayloads[payloadHash]) {
            revert PayloadAlreadyUsed();
        }
        $.consortium.checkProof(payloadHash, proof);
        $.usedPayloads[payloadHash] = true;

        // Confirm deposit against Bascule
        _confirmDeposit($, legacyHash, action.amount);

        // Actually mint
        $.bridgeToken.mint(
            action.recipient,
            action.amount,
            address(0),
            0,
            /// payload has not reversed txid (core representation), reverse to make it compatible with explorer
            reverseBytes32(action.txid),
            action.vout
        );

        emit MintProofConsumed(action.recipient, payloadHash, rawPayload);
        return (action.recipient, action.amount);
    }

    /// @notice          Changes the endianness of a bytes32
    /// @dev             https://graphics.stanford.edu/~seander/bithacks.html#ReverseParallel
    /// @param _b        The bytes32 to reverse
    /// @return v        The reversed value
    function reverseBytes32(bytes32 _b) internal pure returns (bytes32 v) {
        v = _b;

        // swap bytes
        v =
            ((v >> 8) &
                0x00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF) |
            ((v &
                0x00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF) <<
                8);
        // swap 2-byte long pairs
        v =
            ((v >> 16) &
                0x0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF) |
            ((v &
                0x0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF) <<
                16);
        // swap 4-byte long pairs
        v =
            ((v >> 32) &
                0x00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF) |
            ((v &
                0x00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF) <<
                32);
        // swap 8-byte long pairs
        v =
            ((v >> 64) &
                0x0000000000000000FFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF) |
            ((v &
                0x0000000000000000FFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF) <<
                64);
        // swap 16-byte long pairs
        v = (v >> 128) | (v << 128);
    }

    /// @dev Checks that the deposit was validated by the Bascule drawbridge.
    /// @param $ NativeLBTC storage.
    /// @param depositID The unique ID of the deposit.
    /// @param amount The withdrawal amount.
    function _confirmDeposit(
        BridgeTokenAdapterStorage storage $,
        bytes32 depositID,
        uint256 amount
    ) internal {
        IBascule bascule = $.bascule;
        if (address(bascule) != address(0)) {
            bascule.validateWithdrawal(depositID, amount);
        }
    }

    /// @dev `consortium` not zero
    function _changeConsortium(address newVal) internal {
        Assert.zeroAddress(newVal);
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();
        emit ConsortiumChanged(address($.consortium), newVal);
        $.consortium = INotaryConsortium(newVal);
    }

    function _changeBascule(address newVal) internal {
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();
        emit BasculeChanged(address($.bascule), newVal);
        $.bascule = IBascule(newVal);
    }

    /// @dev `treasury` not zero
    function _changeTreasury(address newValue) internal {
        Assert.zeroAddress(newValue);
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();
        address prevValue = $.treasury;
        $.treasury = newValue;
        emit TreasuryAddressChanged(prevValue, newValue);
    }

    /// @dev `treasury` not zero
    function _changeBridgeToken(address newValue) internal {
        Assert.zeroAddress(newValue);
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();
        address prevValue = address($.bridgeToken);
        $.bridgeToken = IBridgeToken(newValue);
        emit BridgeTokenChanged(prevValue, newValue);
    }

    /// @dev allow zero address to disable Stakings
    function _changeAssetRouter(address newVal) internal {
        BridgeTokenAdapterStorage storage $ = _getBridgeTokenAdapterStorage();
        address prevValue = address($.assetRouter);
        $.assetRouter = IAssetRouter(newVal);
        emit AssetRouterChanged(prevValue, newVal);
    }

    function _getBridgeTokenAdapterStorage()
        private
        pure
        returns (BridgeTokenAdapterStorage storage $)
    {
        assembly {
            $.slot := BRIDGE_TOKEN_ADAPTER_STORAGE_LOCATION
        }
    }
}

// SPDX-License-Identifier: LZBL-1.2

pragma solidity ^0.8.20;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { Transfer } from "@layerzerolabs/lz-evm-protocol-v2/contracts/libs/Transfer.sol";

import { ILayerZeroExecutor } from "./interfaces/ILayerZeroExecutor.sol";
import { ILayerZeroTreasury } from "./interfaces/ILayerZeroTreasury.sol";
import { SafeCall } from "./libs/SafeCall.sol";
import { MessageLibBase } from "./MessageLibBase.sol";

struct WorkerOptions {
    uint8 workerId;
    bytes options;
}

struct SetDefaultExecutorConfigParam {
    uint32 eid;
    ExecutorConfig config;
}

struct ExecutorConfig {
    uint32 maxMessageSize;
    address executor;
}

/// @dev base contract for both SendLibBaseE1 and SendLibBaseE2
abstract contract SendLibBase is MessageLibBase, Ownable {
    using SafeCall for address;

    address private constant DEFAULT_CONFIG = address(0);
    uint16 internal constant TREASURY_MAX_COPY = 32;

    uint256 internal immutable treasuryGasLimit;
    uint256 internal treasuryNativeFeeCap;

    // config
    address public treasury;
    mapping(address oapp => mapping(uint32 eid => ExecutorConfig)) public executorConfigs;

    // accumulated fees for workers and treasury
    mapping(address worker => uint256) public fees;

    event ExecutorFeePaid(address executor, uint256 fee);
    event TreasurySet(address treasury);
    event DefaultExecutorConfigsSet(SetDefaultExecutorConfigParam[] params);
    event ExecutorConfigSet(address oapp, uint32 eid, ExecutorConfig config);
    event TreasuryNativeFeeCapSet(uint256 newTreasuryNativeFeeCap);

    error LZ_MessageLib_InvalidMessageSize(uint256 actual, uint256 max);
    error LZ_MessageLib_InvalidAmount(uint256 requested, uint256 available);
    error LZ_MessageLib_TransferFailed();
    error LZ_MessageLib_InvalidExecutor();
    error LZ_MessageLib_ZeroMessageSize();

    constructor(
        address _endpoint,
        uint32 _localEid,
        uint256 _treasuryGasLimit,
        uint256 _treasuryNativeFeeCap
    ) MessageLibBase(_endpoint, _localEid) {
        treasuryGasLimit = _treasuryGasLimit;
        treasuryNativeFeeCap = _treasuryNativeFeeCap;
    }

    function setDefaultExecutorConfigs(SetDefaultExecutorConfigParam[] calldata _params) external onlyOwner {
        for (uint256 i = 0; i < _params.length; ++i) {
            SetDefaultExecutorConfigParam calldata param = _params[i];

            if (param.config.executor == address(0x0)) revert LZ_MessageLib_InvalidExecutor();
            if (param.config.maxMessageSize == 0) revert LZ_MessageLib_ZeroMessageSize();

            executorConfigs[DEFAULT_CONFIG][param.eid] = param.config;
        }
        emit DefaultExecutorConfigsSet(_params);
    }

    /// @dev the new value can not be greater than the old value, i.e. down only
    function setTreasuryNativeFeeCap(uint256 _newTreasuryNativeFeeCap) external onlyOwner {
        // assert the new value is no greater than the old value
        if (_newTreasuryNativeFeeCap > treasuryNativeFeeCap)
            revert LZ_MessageLib_InvalidAmount(_newTreasuryNativeFeeCap, treasuryNativeFeeCap);
        treasuryNativeFeeCap = _newTreasuryNativeFeeCap;
        emit TreasuryNativeFeeCapSet(_newTreasuryNativeFeeCap);
    }

    // ============================ View ===================================
    // @dev get the executor config and if not set, return the default config
    function getExecutorConfig(address _oapp, uint32 _remoteEid) public view returns (ExecutorConfig memory rtnConfig) {
        ExecutorConfig storage defaultConfig = executorConfigs[DEFAULT_CONFIG][_remoteEid];
        ExecutorConfig storage customConfig = executorConfigs[_oapp][_remoteEid];

        uint32 maxMessageSize = customConfig.maxMessageSize;
        rtnConfig.maxMessageSize = maxMessageSize != 0 ? maxMessageSize : defaultConfig.maxMessageSize;

        address executor = customConfig.executor;
        rtnConfig.executor = executor != address(0x0) ? executor : defaultConfig.executor;
    }

    // ======================= Internal =======================
    function _assertMessageSize(uint256 _actual, uint256 _max) internal pure {
        if (_actual > _max) revert LZ_MessageLib_InvalidMessageSize(_actual, _max);
    }

    function _payExecutor(
        address _executor,
        uint32 _dstEid,
        address _sender,
        uint256 _msgSize,
        bytes memory _executorOptions
    ) internal returns (uint256 executorFee) {
        executorFee = ILayerZeroExecutor(_executor).assignJob(_dstEid, _sender, _msgSize, _executorOptions);
        if (executorFee > 0) {
            fees[_executor] += executorFee;
        }
        emit ExecutorFeePaid(_executor, executorFee);
    }

    function _payTreasury(
        address _sender,
        uint32 _dstEid,
        uint256 _totalNativeFee,
        bool _payInLzToken
    ) internal returns (uint256 treasuryNativeFee, uint256 lzTokenFee) {
        if (treasury != address(0x0)) {
            bytes memory callData = abi.encodeCall(
                ILayerZeroTreasury.payFee,
                (_sender, _dstEid, _totalNativeFee, _payInLzToken)
            );
            (bool success, bytes memory result) = treasury.safeCall(treasuryGasLimit, 0, TREASURY_MAX_COPY, callData);

            (treasuryNativeFee, lzTokenFee) = _parseTreasuryResult(_totalNativeFee, _payInLzToken, success, result);
            // fee should be in lzTokenFee if payInLzToken, otherwise in native
            if (treasuryNativeFee > 0) {
                fees[treasury] += treasuryNativeFee;
            }
        }
    }

    /// @dev the abstract process for quote() is:
    /// 0/ split out the executor options and options of other workers
    /// 1/ quote workers
    /// 2/ quote executor
    /// 3/ quote treasury
    /// @return nativeFee, lzTokenFee
    function _quote(
        address _sender,
        uint32 _dstEid,
        uint256 _msgSize,
        bool _payInLzToken,
        bytes calldata _options
    ) internal view returns (uint256, uint256) {
        (bytes memory executorOptions, WorkerOptions[] memory validationOptions) = _splitOptions(_options);

        // quote the verifier used in the library. for ULN, it is a list of DVNs
        uint256 nativeFee = _quoteVerifier(_sender, _dstEid, validationOptions);

        // quote executor
        ExecutorConfig memory config = getExecutorConfig(_sender, _dstEid);
        // assert msg size
        _assertMessageSize(_msgSize, config.maxMessageSize);

        nativeFee += ILayerZeroExecutor(config.executor).getFee(_dstEid, _sender, _msgSize, executorOptions);

        // quote treasury
        (uint256 treasuryNativeFee, uint256 lzTokenFee) = _quoteTreasury(_sender, _dstEid, nativeFee, _payInLzToken);
        nativeFee += treasuryNativeFee;

        return (nativeFee, lzTokenFee);
    }

    /// @dev this interface should be DoS-free if the user is paying with native. properties
    /// 1/ treasury can return an overly high lzToken fee
    /// 2/ if treasury returns an overly high native fee, it will be capped by maxNativeFee,
    ///    which can be reasoned with the configurations
    /// 3/ the owner can not configure the treasury in a way that force this function to revert
    function _quoteTreasury(
        address _sender,
        uint32 _dstEid,
        uint256 _totalNativeFee,
        bool _payInLzToken
    ) internal view returns (uint256 nativeFee, uint256 lzTokenFee) {
